std::vector<int> run_lru(int cap, std::vector<std::vector<int>> ops) {
    LRUCache c(cap);
    std::vector<int> out;
    for (const auto& op : ops) {
        if (op[0] == 0) c.put(op[1], op[2]);
        else out.push_back(c.get(op[1]));
    }
    return out;
}

long long big_lru_sum(int n, int cap) {
    LRUCache c(cap);
    for (int i = 0; i < n; ++i) c.put(i, i);
    long long total = 0;
    for (int i = n - 1000; i < n; ++i) total += c.get(i);
    total += c.get(0);
    return total;
}

