class _Node:
    def __init__(self, key=0, value=0, touched=0):
        self.key, self.value, self.touched = key, value, touched
        self.prev = self.next = None


class TTLCache:
    def __init__(self, capacity, ttl):
        self.capacity, self.ttl = capacity, ttl
        self.map = {}
        self.head, self.tail = _Node(), _Node()
        self.head.next, self.tail.prev = self.tail, self.head

    def _unlink(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _push_front(self, node):
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def _purge(self, now):
        # the tail holds the oldest use, so the expired entries are a suffix
        while self.tail.prev is not self.head and now - self.tail.prev.touched >= self.ttl:
            last = self.tail.prev
            self._unlink(last)
            del self.map[last.key]

    def get(self, key, now):
        self._purge(now)
        node = self.map.get(key)
        if node is None:
            return -1
        node.touched = now
        self._unlink(node)
        self._push_front(node)
        return node.value

    def put(self, key, value, now):
        self._purge(now)
        node = self.map.get(key)
        if node is not None:
            node.value, node.touched = value, now
            self._unlink(node)
            self._push_front(node)
            return
        if len(self.map) == self.capacity:
            last = self.tail.prev
            self._unlink(last)
            del self.map[last.key]
        node = _Node(key, value, now)
        self.map[key] = node
        self._push_front(node)

widget.postlude:
def run_ttl(cap, ttl, ops):
    c = TTLCache(cap, ttl)
    out = []
    for op in ops:
        if op[0] == 0:
            c.put(op[1], op[2], op[3])
        else:
            out.append(c.get(op[1], op[2]))
    return out
